def matrix_scalar_multiple_definition(s=None, a11=None, a12=None, a21=None, a22=None):
    """Matrix scalar multiple definition. Computes the entries of a 2x2 matrix scaled by a scalar.
    Formula: b_{11} = s a_{11},\\quad b_{12} = s a_{12},\\quad b_{21} = s a_{21},\\quad b_{22} = s a_{22}
    Inputs:
        s: scalar multiplier
        a11: entry in row 1 column 1
        a12: entry in row 1 column 2
        a21: entry in row 2 column 1
        a22: entry in row 2 column 2
    Outputs: b11 (entry in row 1 column 1 of result), b12 (entry in row 1 column 2 of result), b21 (entry in row 2 column 1 of result), b22 (entry in row 2 column 2 of result)
    See also: help("matrix_scalar_multiple_definition")
    """
    given = {k: v for k, v in dict(s=s, a11=a11, a12=a12, a21=a21, a22=a22).items() if v is not None}
