def radical_equation(a=None, b=None, c=None, d=None):
    """Radical equation sqrt(ax + b) = cx + d. Solve sqrt(a*x + b) = c*x + d: square, solve, and keep only the roots that satisfy the original equation.
    Formula: \\sqrt{ax+b} = cx+d \\;\\Rightarrow\\; ax+b = (cx+d)^2,\\ cx+d \\ge 0
    Inputs:
        a: coefficient of x under the root (condition: a != 0)
        b: constant under the root
        c: coefficient of x on the right
        d: constant on the right
    Outputs: count (number of solutions (0, 1 or 2)), solutions (the solutions, ascending), extraneous (roots of the squared equation that fail the original (extraneous))
    See also: help("radical_equation")
    """
